create table public.experiments(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(btrim(name)) between 2 and 120),hypothesis text not null check(char_length(btrim(hypothesis)) between 10 and 500),description text check(description is null or char_length(description)<=2000),status text not null default 'draft' check(status in('draft','scheduled','active','paused','completed','ended_early','abandoned','archived')),current_phase text not null default 'planning' check(current_phase in('planning','baseline','intervention','washout','analysis','complete')),study_design text not null default 'baseline_intervention' check(study_design in('baseline_intervention','intervention_only')),baseline_start_date date,baseline_end_date date,intervention_start_date date,intervention_end_date date,planned_start_date date,planned_end_date date,actual_started_at timestamptz,actual_completed_at timestamptz,paused_at timestamptz,ended_early_at timestamptz,adherence_target numeric check(adherence_target between 0 and 100),minimum_baseline_observations integer check(minimum_baseline_observations>0),minimum_intervention_observations integer check(minimum_intervention_observations>0),result_summary text,notes text check(notes is null or char_length(notes)<=4000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,unique(id,user_id),check(baseline_end_date is null or baseline_start_date is not null and baseline_end_date>=baseline_start_date),check(intervention_end_date is null or intervention_start_date is not null and intervention_end_date>=intervention_start_date),check(baseline_end_date is null or intervention_start_date is null or intervention_start_date>baseline_end_date),check(planned_end_date is null or planned_start_date is not null and planned_end_date>=planned_start_date),check(status<>'completed' or actual_completed_at is not null),check(status<>'archived' or archived_at is not null)
);
create table public.experiment_interventions(
 id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.experiments(id) on delete cascade,intervention_type text not null check(intervention_type in('supplement','nutrition_target','hydration_target','sleep_target','habit','protocol','workout','exposure_reduction','medication_observation','custom')),name text not null check(char_length(btrim(name)) between 2 and 120),instructions text check(instructions is null or char_length(instructions)<=2000),target_value numeric,target_value_text text,unit text,frequency_type text check(frequency_type in('daily','weekly','specific_days','once','custom')),frequency_target numeric check(frequency_target is null or frequency_target>0),timing_text text,linked_planned_activity_id uuid references public.planned_activities(id) on delete set null,linked_user_protocol_id uuid references public.user_protocols(id) on delete set null,linked_workout_template_id uuid references public.workout_templates(id) on delete set null,custom_definition jsonb,is_primary boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index experiment_one_primary_intervention_idx on public.experiment_interventions(experiment_id) where is_primary;
create table public.experiment_outcomes(
 id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.experiments(id) on delete cascade,outcome_role text not null check(outcome_role in('primary','secondary')),outcome_type text not null check(outcome_type in('symptom_occurrence','symptom_severity','symptom_duration','sleep_quality','mood','energy','weight','habit_adherence','protocol_adherence','workout_performance','custom_numeric','custom_binary')),name text not null,symptom_id uuid references public.symptoms(id) on delete restrict,custom_symptom_name text,checkin_field text,metric_key text,custom_metric_definition jsonb,aggregation_method text not null default 'average' check(aggregation_method in('average','median','sum','count','frequency','percentage','minimum','maximum','latest','change_from_baseline')),expected_direction text check(expected_direction in('increase','decrease','maintain','unknown')),measurement_frequency text,unit text,minimum_observations integer check(minimum_observations is null or minimum_observations>0),display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(outcome_type not like 'symptom_%' or symptom_id is not null or char_length(btrim(custom_symptom_name)) between 2 and 120),check(outcome_type not like 'custom_%' or custom_metric_definition is not null)
);
create unique index experiment_one_primary_outcome_idx on public.experiment_outcomes(experiment_id) where outcome_role='primary';
create table public.experiment_condition_links(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.experiments(id) on delete cascade,user_condition_id uuid not null references public.user_conditions(id) on delete cascade,created_at timestamptz not null default now(),unique(experiment_id,user_condition_id));
create table public.experiment_phase_events(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.experiments(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,event_type text not null check(event_type in('created','scheduled','baseline_started','intervention_started','paused','resumed','ended_early','abandoned','completed','archived','restored','configuration_changed')),from_status text,to_status text,from_phase text,to_phase text,occurred_at timestamptz not null default now(),reason text,metadata jsonb,created_at timestamptz not null default now());
create table public.experiment_measurements(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references public.experiments(id) on delete cascade,experiment_outcome_id uuid not null references public.experiment_outcomes(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,measured_at timestamptz not null,phase text not null check(phase in('baseline','intervention','analysis')),numeric_value numeric,boolean_value boolean,text_value text,unit text,source_type text not null check(source_type in('daily_checkin','symptom_event','health_event','habit_completion','protocol_completion','workout_session','planned_activity_occurrence','custom_manual','calculated_snapshot')),source_record_id uuid,is_manual boolean not null default false,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(numeric_value,boolean_value,text_value)=1),unique(experiment_outcome_id,source_type,source_record_id));
create table public.experiment_results(id uuid primary key default gen_random_uuid(),experiment_id uuid not null unique references public.experiments(id) on delete cascade,generated_at timestamptz not null default now(),baseline_observation_count integer not null default 0,intervention_observation_count integer not null default 0,baseline_completeness numeric check(baseline_completeness between 0 and 100),intervention_completeness numeric check(intervention_completeness between 0 and 100),adherence_percentage numeric check(adherence_percentage between 0 and 100),data_quality_score numeric check(data_quality_score between 0 and 100),data_quality_label text check(data_quality_label in('limited_data','moderate_data','strong_personal_evidence')),primary_baseline_value numeric,primary_intervention_value numeric,primary_absolute_change numeric,primary_percent_change numeric,primary_result_text text,secondary_results jsonb,limitations jsonb,analysis_version text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.experiment_templates(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text,hypothesis_template text not null,intervention_type text not null,intervention_defaults jsonb not null default '{}',primary_outcome_defaults jsonb not null default '{}',secondary_outcome_defaults jsonb not null default '[]',baseline_days integer not null default 7 check(baseline_days>0),intervention_days integer not null default 21 check(intervention_days>0),safety_notes text,is_active boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create index experiments_user_status_idx on public.experiments(user_id,status) where archived_at is null;create index experiments_user_phase_idx on public.experiments(user_id,current_phase) where archived_at is null;create index experiments_dates_idx on public.experiments(planned_start_date,planned_end_date);create index experiment_interventions_experiment_idx on public.experiment_interventions(experiment_id);create index experiment_outcomes_experiment_idx on public.experiment_outcomes(experiment_id,outcome_role,display_order);create index experiment_condition_links_condition_idx on public.experiment_condition_links(user_condition_id);create index experiment_phase_events_timeline_idx on public.experiment_phase_events(experiment_id,occurred_at);create index experiment_measurements_phase_idx on public.experiment_measurements(experiment_id,phase,measured_at);create index experiment_measurements_outcome_idx on public.experiment_measurements(experiment_outcome_id,measured_at);
do $$declare t text;begin foreach t in array array['experiments','experiment_interventions','experiment_outcomes','experiment_measurements','experiment_results','experiment_templates'] loop execute format('create trigger %I before update on public.%I for each row execute function public.axvital_planning_set_updated_at()',t||'_set_updated_at',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['experiments','experiment_interventions','experiment_outcomes','experiment_condition_links','experiment_phase_events','experiment_measurements','experiment_results','experiment_templates'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "Authenticated users read experiment templates" on public.experiment_templates for select to authenticated using(is_active);
create policy "Users manage own experiments" on public.experiments for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
do $$declare t text;begin foreach t in array array['experiment_interventions','experiment_outcomes','experiment_condition_links','experiment_results'] loop execute format('create policy %I on public.%I for all to authenticated using(exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid()))) with check(exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid())))',t||'_owner',t);end loop;end$$;
create policy "Users manage own phase events" on public.experiment_phase_events for all to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid()))) with check(user_id=(select auth.uid()) and exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid())));
create policy "Users manage own measurements" on public.experiment_measurements for all to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid()))) with check(user_id=(select auth.uid()) and exists(select 1 from public.experiments e where e.id=experiment_id and e.user_id=(select auth.uid())));

create function public.transition_experiment(target_id uuid,action text,reason_text text default null) returns public.experiments language plpgsql security invoker set search_path='' as $$declare old public.experiments;next_status text;next_phase text;stamp timestamptz:=now();event_name text;begin select * into old from public.experiments where id=target_id and user_id=(select auth.uid()) for update;if old.id is null then raise exception 'Experiment not found';end if;
if action='activate' and old.status='draft' then if not exists(select 1 from public.experiment_interventions where experiment_id=old.id and is_primary) or not exists(select 1 from public.experiment_outcomes where experiment_id=old.id and outcome_role='primary') then raise exception 'Experiment configuration incomplete';end if;next_status:='active';next_phase:=case when old.study_design='baseline_intervention' then 'baseline' else 'intervention' end;event_name:=case when next_phase='baseline' then 'baseline_started' else 'intervention_started' end;
elsif action='start_intervention' and old.status='active' and old.current_phase='baseline' then next_status:='active';next_phase:='intervention';event_name:='intervention_started';
elsif action='pause' and old.status='active' then next_status:='paused';next_phase:=old.current_phase;event_name:='paused';
elsif action='resume' and old.status='paused' then next_status:='active';next_phase:=old.current_phase;event_name:='resumed';
elsif action='complete' and old.status in('active','paused') then next_status:='completed';next_phase:='complete';event_name:='completed';
elsif action='end_early' and old.status in('active','paused') then next_status:='ended_early';next_phase:='analysis';event_name:='ended_early';
elsif action='abandon' and old.status in('draft','scheduled','active','paused') then next_status:='abandoned';next_phase:='complete';event_name:='abandoned';else raise exception 'Invalid experiment transition';end if;
update public.experiments set status=next_status,current_phase=next_phase,actual_started_at=case when action='activate' then coalesce(actual_started_at,stamp) else actual_started_at end,actual_completed_at=case when action='complete' then stamp else actual_completed_at end,paused_at=case when action='pause' then stamp when action='resume' then null else paused_at end,ended_early_at=case when action='end_early' then stamp else ended_early_at end where id=old.id returning * into old;insert into public.experiment_phase_events(experiment_id,user_id,event_type,from_status,to_status,from_phase,to_phase,reason)values(old.id,(select auth.uid()),event_name,old.status,next_status,old.current_phase,next_phase,reason_text);return old;end$$;grant execute on function public.transition_experiment(uuid,text,text) to authenticated;

insert into public.experiment_templates(slug,name,description,hypothesis_template,intervention_type,intervention_defaults,primary_outcome_defaults,baseline_days,intervention_days,safety_notes,display_order) values
('magnesium-sleep','Magnesium and Sleep','Compare self-reported sleep quality before and during a reviewed supplement routine.','I believe my reviewed magnesium routine may affect my sleep quality.','supplement','{"frequency_type":"daily"}','{"outcome_type":"sleep_quality","name":"Sleep quality","aggregation_method":"average"}',7,21,'Confirm with a qualified professional that the supplement and amount are appropriate for you.',10),
('hydration-energy','Hydration and Energy','Compare energy while following a hydration target.','I believe meeting a consistent hydration target may affect my energy.','hydration_target','{"unit":"oz","frequency_type":"daily"}','{"outcome_type":"energy","name":"Energy","aggregation_method":"average"}',7,21,null,20),
('caffeine-migraine','Caffeine and Migraine','Compare migraine frequency while following a reviewed caffeine limit.','I believe following a consistent caffeine limit may affect migraine frequency.','exposure_reduction','{"unit":"mg","frequency_type":"daily"}','{"outcome_type":"symptom_occurrence","name":"Migraine frequency","aggregation_method":"count"}',7,21,null,30),
('protein-recovery','Protein and Recovery','Compare a personal recovery measure while following a protein target.','I believe meeting a consistent protein target may affect my recovery.','nutrition_target','{"unit":"g","frequency_type":"daily"}','{"outcome_type":"custom_numeric","name":"Recovery rating","aggregation_method":"average"}',7,21,null,40),
('alcohol-free-sleep','Alcohol-Free Sleep Test','Compare sleep quality during an alcohol-free intervention.','I believe avoiding alcohol may affect my sleep quality.','exposure_reduction','{"target_value":0,"frequency_type":"daily"}','{"outcome_type":"sleep_quality","name":"Sleep quality","aggregation_method":"average"}',7,21,null,50),
('consistent-bedtime','Consistent Bedtime','Compare sleep quality while following a consistent bedtime.','I believe keeping a consistent bedtime may affect my sleep quality.','sleep_target','{"frequency_type":"daily"}','{"outcome_type":"sleep_quality","name":"Sleep quality","aggregation_method":"average"}',7,21,null,60),
('daily-walking-mood','Daily Walking and Mood','Compare mood while following a daily walking plan.','I believe daily walking may affect my mood.','habit','{"frequency_type":"daily"}','{"outcome_type":"mood","name":"Mood","aggregation_method":"average"}',7,21,null,70),
('supplement-symptom','Supplement and Symptom Severity','Compare a selected symptom before and during a reviewed supplement routine.','I believe my reviewed supplement routine may affect the severity of a symptom I track.','supplement','{"frequency_type":"daily"}','{"outcome_type":"symptom_severity","name":"Symptom severity","aggregation_method":"average"}',7,21,'Confirm with a qualified professional that the supplement and amount are appropriate for you.',80) on conflict(slug) do nothing;
